int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i;
    unsigned char *dest = to;

    for (i = 0; i < fromlen; i++) {
        if (dest >= to + tolen - 1) {
            return -1; // Output buffer overflow
        }

        switch (from[i]) {
            case PATH_COMPONENT_TYPE_SYMLINK:
                *dest++ = '$';
                break;
            case PATH_COMPONENT_TYPE_DIR:
                *dest++ = '/';
                break;
            case PATH_COMPONENT_TYPE_FILE:
                *dest++ = from[i];
                break;
            case PATH_COMPONENT_TYPE_RELATIVE:
                *dest++ = '.';
                if (i + 1 < fromlen && from[i + 1] == PATH_COMPONENT_TYPE_DIR) {
                    *dest++ = '.';
                    i++;
                }
                break;
            default:
                *dest++ = from[i];
        }
    }

    *dest = '\0';
    return 0;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0, j = 0;
    unsigned char *end = to + tolen;

    while (i < fromlen && j < tolen - 1) {
        unsigned char type = from[i];

        switch (type) {
            case PATH_COMPONENT_TYPE_SYMLINK:
                if (j + 2 < tolen) {
                    to[j++] = '.';
                    to[j++] = '.';
                }
                break;
            case PATH_COMPONENT_TYPE_DIRECTORY:
                if (j < tolen) {
                    to[j++] = '.';
                }
                break;
            case PATH_COMPONENT_TYPE_FILE:
                if (j < tolen) {
                    to[j++] = from[i + 1];
                }
                break;
            default:
                return -EINVAL;
        }

        i += 2;
    }

    if (j >= tolen) {
        return -ENAMETOOLONG;
    }

    to[j] = '\0';
    return 0;
}

