int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    if (tolen < 1) {
        return -EINVAL;
    }

    while (i < fromlen && j < tolen - 1) {
        unsigned char type = from[i];

        if (type == PATH_COMPONENT_TYPE_SLASH) {
            to[j++] = '/';
        } else if (type == PATH_COMPONENT_TYPE_DOT) {
            to[j++] = '.';
        } else if (type == PATH_COMPONENT_TYPE_SYMLINK) {
            int len = from[i + 1];
            i += 2;
            if (i + len > fromlen) {
                return -EINVAL;
            }
            if (j + len >= tolen - 1) {
                return -ENAMETOOLONG;
            }
            memcpy(&to[j], &from[i], len);
            j += len;
            i += len;
        } else if (type == PATH_COMPONENT_TYPE_DIR) {
            to[j++] = '.';
            to[j++] = '/';
        } else {
            int len = from[i + 1];
            i += 2;
            if (i + len > fromlen) {
                return -EINVAL;
            }
            if (j + len >= tolen - 1) {
                return -ENAMETOOLONG;
            }
            memcpy(&to[j], &from[i], len);
            j += len;
            i += len;
        }

        i++;
    }

    to[j] = '\0';
    return 0;
}

int path_to_char(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i;
    int pos = 0;

    for (i = 0; i < fromlen; i++) {
        unsigned char type = from[i] & 0xF0;
        unsigned char len = from[i] & 0x0F;

        if (pos >= tolen) {
            return -1; // Output buffer is full
        }

        switch (type) {
            case 0x00: // Symlink
                if (pos + len >= tolen) {
                    return -1; // Output buffer is full
                }
                memcpy(to + pos, from + i + 1, len);
                pos += len;
                break;
            case 0x10: // Directory indicator
                to[pos++] = '/';
                break;
            case 0x20: // File name
                if (pos + len >= tolen) {
                    return -1; // Output buffer is full
                }
                memcpy(to + pos, from + i + 1, len);
                pos += len;
                break;
            default:
                return -1; // Unsupported component type
        }
    }

    if (pos >= tolen) {
        return -1; // Output buffer is full
    }

    to[pos] = '\0'; // Null terminate the string
    return 0;
}
